code:
// The app's OWN sessions in the Glance graph — the STUDIO NETWORK team (`org-planning-studio`, #3317)
// rendered through the existing Team→Glance adapter (`buildOrgFleetData`), plus one node per LIVE
// request session edged to whoever filed it (#debug-nodes-hang-off-the-session-that-filed-them).
// Pure + React-free so it's unit-testable.
//
// THE SYNTHETIC PROJECT NODE IS GONE (#the-app-drills-into-a-project-that-was-deleted). #3319 invented a
// fixed L0 node, `app:base-studio-code`, because the app had no project row of its own to hang these
// sessions off. It has one now: the `base-studio-code` hub was migrated into `studio-code` and deleted,
// so the phantom had become a SECOND node for the same app — and it was the one every studio session and
// every live debug session hung off, i.e. the deleted one. {@link withStudioSessions} folds them into the
// real project's drill instead, and nothing points at a key with no hub.
import { surfacePaneIdForNode } from "@/features/glance/lib/surfaceSpawn";
import { crateDrillGraph, type CrateDrillDoc } from "@/features/glance/lib/surfaceNodes";
import { augmentStudioNetworkForRequests, expandStudioPerTechnology, requestNodeLabel, studioNetworkForArchitect, STUDIO_NETWORK_ID, type Team, type RequestNodeSpec, type OriginHostResolver } from "@/features/teams";
import { requestIdFromNodeId, requestIdFromPaneId, requestNodeId, requestPaneId } from "@/shared/lib/session/requestSpawn";
import type { Persona } from "@/features/personas";
import {
  TEAMS_STUDIO_SESSION_ID, SOUND_STUDIO_SESSION_ID,
  INTEGRATION_STUDIO_SESSION_ID, studioPaneTech,
  librarianSessionId, designerSessionId,
} from "@/shared/lib/session/systemSessions";
import { buildOrgFleetData, livePanesForProject } from "@/features/glance/lib/glanceFleet";
import type { GlanceData } from "@/features/glance/lib/glanceData";
import { COLGAP, ROWGAP, NW, NH, architectIdOfNode } from "@/features/glance/lib/glanceGraph";
import type { GHealth, GActivity, GRawNode, GNode, GEdge } from "@/features/glance/lib/glanceGraph";

/**
 * The plan key of the project THIS APP is developed in — the one whose drill also shows the app-owned
 * studio sessions ({@link withStudioSessions}).
 *
 * A real key, with a hub on disk, replacing the synthetic `app:base-studio-code` that had none. It is
 * still a constant rather than something derived, and deliberately so: nothing in the model says which
 * of a user's projects IS the app, and inventing a derivation (match a linked repo against the app's
 * source root, slugify the repo's folder name) would be a guess dressed as a rule — the app repo is
 * `base-studio-code` and the project is `studio-code`, so the obvious derivations are already wrong.
 * Making it user-designated is the next slice; recorded, not built.
 *
 * On an install with no such project this simply never matches, and the app-owned sessions stay reachable
 * through the ARCHITECT node's drill ({@link buildArchitectFleetData}), which renders the same team.
 */
export const APP_PROJECT_KEY = "studio-code";

/** Whether a drilled project key is the app's own — the one drill that also draws the studio sessions. */
export function isAppProject(key: string | null | undefined): boolean {
  return !!key && key === APP_PROJECT_KEY;
}

/**
 * Every live session pane the DRILLED project owns — what "End N sessions" counts and ends.
 *
 * `livePanesForProject` alone matches the `<key>:` pane prefix, which is right for a normal project
 * and WRONG for the app's own: a debug session's pane is `debug-studio:req-<id>` (the prefix is what
 * makes it full-capability, `isFullCapabilitySession`), so `studio-code`'s counter read 0 while the
 * very same drill was DRAWING those sessions as nodes (`withProjectRequestNodes`). The graph showed
 * them and the counter denied them.
 *
 * Request sessions only. The standing studios — designer, librarian, architect, sound-designer,
 * integrator — are app-owned SINGLETONS that outlive any one project, and sweeping them up in a
 * project's bulk "End sessions" would kill surfaces the user never aimed at. They stay endable one at
 * a time from their own node.
 */
export function livePanesForDrilledProject(
  projectKey: string,
  livePaneIds: ReadonlySet<string>,
  /** The live request sessions, as the drill drew them. Omitted ⇒ only the app project's are counted,
   *  which is the pre-#a-projects-debug-sessions-are-drawn-but-not-counted behaviour. */
  requests: readonly RequestNodeSpec[] = [],
): string[] {
  const own = livePanesForProject(projectKey, livePaneIds);
  // COUNT WHAT THE DRILL DREW. The app project draws EVERY live request session — the studio fold, the
  // director's own, and the unparented sweep — so its rule stays "every request pane". Any other
  // project draws exactly the requests ITS director filed, by the origin rule in
  // `withProjectRequestNodes`, so that is the rule here too.
  //
  // Deriving it from the drawers rather than restating it is the point. This function already carried a
  // second condition that HAPPENED to agree with them for one project and disagreed for every other:
  // Network Monitor ran a director and two debug sessions, the drill rendered both as nodes, and the
  // toolbar reported zero.
  const mine = isAppProject(projectKey)
    ? (pid: string) => requestIdFromPaneId(pid) !== null
    : (pid: string) => {
        const id = requestIdFromPaneId(pid);
        return id !== null && requests.some(
          (r) => r.id === id && (r.origin ?? "").trim() === `${projectKey}:${DIRECTOR_NODE}`,
        );
      };
  // De-duplicated against `own` rather than assumed disjoint: the prefixes differ today, but a
  // concatenation that silently double-counts is the kind of thing a counter should not risk.
  const seen = new Set(own);
  const extra = [...livePaneIds].filter((pid) => !seen.has(pid) && mine(pid));
  return [...own, ...extra];
}

/**
 * The base-studio-code project's drilled graph — the Studio Network team's positions (the app-owned
 * studio sessions) as nodes and its relationships as edges, plus one node per LIVE request session,
 * each hanging off the session that filed its request. Returns `null` when the team isn't present (so
 * the caller falls back to the empty/sample graph rather than crashing). Pure.
 *
 * There is no standing `debugger` node any more (#debug-nodes-hang-off-the-session-that-filed-them) and
 * so no toggle parameter: debug work appears exactly when there is some, named for what it is.
 */
export function buildStudioFleetData(
  teams: readonly Team[],
  personas: Persona[],
  /** The live request sessions — each becomes its own labelled, openable node. */
  requests: readonly RequestNodeSpec[] = [],
): GlanceData | null {
  const team = teams.find((t) => t.id === STUDIO_NETWORK_ID);
  if (!team) return null;
  // PER-TECHNOLOGY, like the architect's drill (#the-project-drill-draws-per-technology-studio-nodes).
  // The packaged team describes ROLES, so this drill used to draw one `designer` node that every
  // technology's requests collapsed onto — and `studioNodeForOrigin` prefers the per-tech candidate,
  // so expanding FIRST is what makes a request edge to the session that actually filed it rather than
  // to the role fallback. Expanding before the augment is load-bearing for exactly that reason.
  const expanded = expandStudioPerTechnology(team);
  return buildOrgFleetData(augmentStudioNetworkForRequests(expanded, requests, studioNodeForOrigin), personas);
}

/**
 * Fold the app-owned SESSIONS (and the live request sessions hanging off them) into a project's fleet
 * graph (#the-app-drills-into-a-project-that-was-deleted) — so the app's own project drills into one
 * graph holding both its plan.db workers and the studios that build it, instead of the app owning a
 * second, synthetic project node beside it.
 *
 * ONLY the nodes that resolve to an app-owned pane are folded. That is exactly "a session you can open",
 * and it is also what makes the fold safe: the studio team's RESOURCE nodes are named for domains
 * (`algorithms`, `sounds`, `integrations`) and the app's own fleet has streams with those very ids, so
 * folding them would either be dropped as a collision or, worse, hand a studio's edges to an unrelated
 * worker. The libraries already have their own L0 home in the fenced band (#2571/#3133); the sessions
 * did not, which is the gap this closes. The team's `planner` position drops out by the same rule — it
 * has no fixed session, so it would draw a node that does nothing.
 *
 * An id already present in the fleet graph is left ALONE rather than merged over: a fleet stream that
 * happens to share a studio node's id is a different thing with the same name, and the fleet owns its
 * own drill. An edge survives only when BOTH its ends were folded, so a skipped node can never leave a
 * studio relationship pointing at a fleet cell.
 *
 * Idempotent, and a no-op when the Studio Network team is absent. Pure.
 */
export function withStudioSessions(
  data: GlanceData,
  teams: readonly Team[],
  personas: Persona[],
  requests: readonly RequestNodeSpec[] = [],
): GlanceData {
  const studio = buildStudioFleetData(teams, personas, requests);
  if (!studio) return data;
  const present = new Set(data.rawNodes.map((n) => n.id));
  const nodes = studio.rawNodes.filter((n) => !present.has(n.id) && !n.resource && !!studioPaneIdForNode(n.id));
  if (!nodes.length) return data;
  const folded = new Set(nodes.map((n) => n.id));
  return {
    ...data,
    rawNodes: [...data.rawNodes, ...nodes],
    rawEdges: [...data.rawEdges, ...studio.rawEdges.filter((e) => folded.has(e.from) && folded.has(e.to))],
  };
}

/** The node id a project's DIRECTOR carries in its own fleet drill. Mirrors `directorPaneId`'s tail —
 *  the drill's node ids are stream ids, and the director's is the reserved `director`. */
const DIRECTOR_NODE = "director";

/** Namespace prefix for ANOTHER project's director, drawn inside the studio-code drill. Prefixed so it
 *  can never collide with the reserved bare `director` — which is THIS drill's own director — nor with
 *  a stream id. */
export const PROJECT_DIRECTOR_PREFIX = "director:";
/** The node id for another project's director. */
export const projectDirectorNodeId = (projectKey: string): string => `${PROJECT_DIRECTOR_PREFIX}${projectKey}`;
/** The project key behind a `director:<key>` node id, or `null` for anything else. */
export const projectKeyOfDirectorNode = (nodeId: string): string | null =>
  nodeId.startsWith(PROJECT_DIRECTOR_PREFIX) ? nodeId.slice(PROJECT_DIRECTOR_PREFIX.length) : null;

/** One project's director, as the caller supplies it. */
export interface ProjectDirectorSpec {
  /** The project key — `projectSlug(name)`, the same one its panes are named from. */
  key: string;
  /** The project's DISPLAY title, which is what the node is labelled from. */
  title: string;
}

/**
 * Add a node per OTHER project's director, edged from the studio-code director
 * (#the-studio-code-director-is-the-architect).
 *
 * WITHIN THE APP'S OWN DRILL, the studio-code director coordinates every other project's director.
 * So this drill grows a tier — the app's own director on the right, every project director and system
 * session beside each other one layer left, and each debug session left of whoever spawned it.
 *
 * THIS PARAGRAPH USED TO SAY "there is no architect persona to assign a project to any more: one
 * director is responsible for everything", and that was live in the tree at the same time as the
 * persona-ownership machinery in `glanceData` — two stories about the architect, contradicting each
 * other, both true once. `l0-is-scoped-to-its-network` settled it: THE ARCHITECT IS PER NETWORK. Each
 * network owns exactly one, running at `network-<slug>:architect`, and a project belongs to an
 * architect by belonging to its network. What survives from the old sentence is only what it was
 * really describing — the shape of the app's OWN drill — which is what it now says.
 *
 * EDGE DIRECTION IS THE LAYOUT. A Glance edge is "FROM depends on TO" and the DAG lays a target one
 * layer LEFT of its source, which is how `served-by` already puts studio sessions left of the
 * architect. Drawing `director → director:<key>` is therefore what places the project directors on the
 * studio-code director's left, and nothing about position is hand-placed.
 *
 * It also removes the reason debug sessions float. {@link withUnparentedRequestNodes} exists for "an
 * origin that is PRESENT but resolves to nothing this graph draws — a request filed by a human at a
 * shell, or BY ANOTHER PROJECT'S DIRECTOR". Once every director is a node, the second half of that
 * sentence stops being true and those requests attach by origin like any other; the sweep shrinks to
 * its honest residue.
 *
 * Skips the app's own key (it is the `director` node this hangs from, not a peer) and anything already
 * drawn. Idempotent and pure.
 */
export function withProjectDirectorNodes(
  data: GlanceData,
  directors: readonly ProjectDirectorSpec[] = [],
): GlanceData {
  if (!directors.length) return data;
  const present = new Set(data.rawNodes.map((n) => n.id));
  if (!present.has(DIRECTOR_NODE)) return data; // no root drawn ⇒ nothing to hang them from
  const seen = new Set<string>();
  const mine = directors.filter((d) => {
    const key = d.key?.trim();
    if (!key || isAppProject(key)) return false; // the app's own director IS the root
    const id = projectDirectorNodeId(key);
    if (present.has(id) || seen.has(id)) return false;
    seen.add(id);
    return true;
  });
  if (!mine.length) return data;
  return {
    ...data,
    rawNodes: [
      ...data.rawNodes,
      ...mine.map((d) => ({
        id: projectDirectorNodeId(d.key),
        // "project title + director" — the title people recognise, and the word that says what it is.
        // The KEY is deliberately not the label: it is a slug, and a graph of slugs reads as internals.
        slug: `${(d.title || d.key).trim()} director`,
        role: "infra" as const,
        roleLabel: "director",
        health: "healthy" as GHealth,
        activity: "idle" as GActivity,
      })),
    ],
    rawEdges: [
      ...data.rawEdges,
      ...mine.map((d) => ({ from: DIRECTOR_NODE, to: projectDirectorNodeId(d.key), kind: "api" as const })),
    ],
  };
}

/** The raw node a live request session draws as — ONE definition, shared by every drawer below.
 *
 *  It was duplicated once and that is exactly enough. A node drawn by the last-resort sweep must be
 *  INDISTINGUISHABLE from one drawn against its director: "this session had no relationship" must not
 *  read to the user as "this session is a different kind of thing". Same role, same label, same live
 *  states — only the EDGE differs, which is the only thing that actually does. */
function requestRawNode(r: RequestNodeSpec): GRawNode {
  return {
    id: requestNodeId(r.id),
    slug: requestNodeLabel(r.title),
    role: "infra",
    roleLabel: "debugger",
    health: "healthy" as GHealth,
    activity: "building" as GActivity,
  };
}

/**
 * Add a node per live request session that THIS project's director filed
 * (#debug-nodes-hang-off-the-session-that-filed-them).
 *
 * A director is the one non-studio session allowed to file a global `bsc request` (workers are denied
 * the queue on purpose — director-protocol.md), so its requests have an origin like
 * `myproject:director` that resolves to no Studio Network position. Rendering them on the studio graph
 * would leave them unparented, and an unparented node reads as a bug; dropping them would make an
 * app-started session invisible, which is the one thing every request node exists to prevent. They
 * belong HERE, against the director that filed them, resolved by the same origin rule.
 *
 * Idempotent, and a no-op for a project whose director filed nothing. Pure.
 */
export function withProjectRequestNodes(
  data: GlanceData,
  projectKey: string,
  requests: readonly RequestNodeSpec[] = [],
): GlanceData {
  if (!projectKey || !requests.length) return data;
  const present = new Set(data.rawNodes.map((n) => n.id));
  if (!present.has(DIRECTOR_NODE)) return data; // no director drawn ⇒ nothing to hang them off
  const mine = requests.filter(
    (r) => (r.origin ?? "").trim() === `${projectKey}:${DIRECTOR_NODE}` && !present.has(requestNodeId(r.id)),
  );
  if (!mine.length) return data;
  const nodes: GRawNode[] = mine.map(requestRawNode);
  return {
    ...data,
    rawNodes: [...data.rawNodes, ...nodes],
    // A Glance edge is "FROM depends on TO", which is the INVERSE of the org relationship it comes from
    // — `buildOrgFleetData` reverses every one. So the studio graph draws `designer → debugger-req-N`
    // (the designer is blocked on that fix), and this must match: `director → debugger-req-N`. Authored
    // by hand rather than through the org adapter, this was the one edge pointing the other way, and only
    // running it against real rows showed it.
    rawEdges: [...data.rawEdges, ...mine.map((r) => ({ from: DIRECTOR_NODE, to: requestNodeId(r.id), kind: "api" as const }))],
  };
}

/**
 * Edge each live request session to the OTHER project's director that filed it
 * (#the-studio-code-director-is-the-architect).
 *
 * This is the case {@link withUnparentedRequestNodes} names and cannot serve: "an origin that is
 * PRESENT but resolves to nothing this graph draws — … or BY ANOTHER PROJECT'S DIRECTOR". It resolved
 * to nothing only because that director had no node. {@link withProjectDirectorNodes} gives it one, so
 * the relationship is now drawable and the session stops floating.
 *
 * Runs AFTER the director tier and BEFORE the sweep, for the ordering reason the sweep documents: a
 * drawer that wants to draw an edge must get there first, or the sweep draws the node bare and the
 * later drawer skips it as already present — silently losing the edge.
 *
 * Same node shape as every other drawer ({@link requestRawNode}), because "this one was filed by
 * another project's director" must not read as a different KIND of thing. Only the edge differs.
 *
 * Idempotent and pure.
 */
export function withDirectorRequestNodes(
  data: GlanceData,
  requests: readonly RequestNodeSpec[] = [],
): GlanceData {
  if (!requests.length) return data;
  const present = new Set(data.rawNodes.map((n) => n.id));
  const seen = new Set<string>();
  const hosted = requests.flatMap((r) => {
    const origin = (r.origin ?? "").trim();
    if (!origin.endsWith(`:${DIRECTOR_NODE}`)) return [];
    const key = origin.slice(0, -`:${DIRECTOR_NODE}`.length);
    // The app's own director is the bare `director` root; every other is its prefixed node.
    const host = isAppProject(key) ? DIRECTOR_NODE : projectDirectorNodeId(key);
    if (!present.has(host)) return []; // that director is not drawn ⇒ leave it to the sweep
    const id = requestNodeId(r.id);
    if (present.has(id) || seen.has(id)) return [];
    seen.add(id);
    return [{ spec: r, host, id }];
  });
  if (!hosted.length) return data;
  return {
    ...data,
    rawNodes: [...data.rawNodes, ...hosted.map((h) => requestRawNode(h.spec))],
    // `FROM depends on TO`, matching every other request edge here: the director is blocked on the fix.
    rawEdges: [...data.rawEdges, ...hosted.map((h) => ({ from: h.host, to: h.id, kind: "api" as const }))],
  };
}

/**
 * The LAST-RESORT sweep: a node for every live request session that no earlier drawer gave one
 * (#every-live-debug-session-is-visible-in-the-app-drill).
 *
 * VISIBILITY IS UNCONDITIONAL HERE; a relationship is not. {@link withStudioSessions} draws a request
 * whose origin names a studio session (edged to it) and one with NO origin at all (unparented), and
 * {@link withProjectRequestNodes} draws one filed by THIS project's director (edged to it). Between
 * them they missed a real case: an origin that is PRESENT but resolves to nothing this graph draws — a
 * request filed by a human at a shell (`--from`), or by ANOTHER project's director. Such a session ran
 * busy with no node in any graph, which is the one outcome every request node exists to prevent.
 *
 * IT RUNS LAST, AND THAT ORDERING IS THE DESIGN. Relaxing the team-layer filter to draw every
 * unhostable origin unparented would ALSO catch a `<thisProject>:director` request — and because the
 * studio fold runs BEFORE {@link withProjectRequestNodes}, that request would be drawn unparented first
 * and then skipped as already present, silently losing the director edge it was supposed to carry. A
 * sweep that only ADDS what nothing else drew cannot take an edge away from a drawer that wanted one.
 *
 * IT EDGES TO THE ARCHITECT, and it did not always. The original drew no edge at all, on the reasoning
 * that there was "nothing truthful to point at" — which was CORRECT WHEN WRITTEN and stopped being so
 * when the app's own director became the architect (#the-studio-code-director-is-the-architect). The
 * requests that reach this sweep are the ones filed by a human at a shell (`--from kevin`), and the
 * global tooling queue is exactly what the architect owns: it is the tier that answers for everything
 * no project director does. Pointing at it is a fact about the model, not a target invented to avoid a
 * bare node — which is the distinction {@link studioNodeForOrigin} returns null to protect.
 *
 * It still draws NO edge when the root is absent (a non-app project's drill never has one), so the
 * guarantee this sweep exists for — a live session is VISIBLE, whatever its origin — never depends on
 * finding a parent. The node is openable and stoppable on its own either way
 * ({@link studioPaneIdForNode} resolves its pane from the node id alone), which is what supervision
 * actually requires.
 *
 * Idempotent, and a no-op once every request has a node. Pure.
 */
export function withUnparentedRequestNodes(
  data: GlanceData,
  requests: readonly RequestNodeSpec[] = [],
): GlanceData {
  if (!requests.length) return data;
  const present = new Set(data.rawNodes.map((n) => n.id));
  // De-duplicated against the drawn set AND against itself. `present` is sampled once, before anything
  // is pushed, so two rows carrying the same id would both pass it and draw one session twice.
  const seen = new Set<string>();
  const orphans = requests.filter((r) => {
    const id = requestNodeId(r.id);
    if (present.has(id) || seen.has(id)) return false;
    seen.add(id);
    return true;
  });
  if (!orphans.length) return data;
  // `FROM depends on TO`, matching every other request edge here: the architect is blocked on the fix.
  const edges = present.has(DIRECTOR_NODE)
    ? orphans.map((r) => ({ from: DIRECTOR_NODE, to: requestNodeId(r.id), kind: "api" as const }))
    : [];
  return {
    ...data,
    rawNodes: [...data.rawNodes, ...orphans.map(requestRawNode)],
    rawEdges: [...data.rawEdges, ...edges],
  };
}

/**
 * The ARCHITECT node's drilled graph (#architect-node-expands-into-system-sessions) — the system
 * sessions it commands, rendered through the SAME Team→Glance adapter the base-studio-code node uses.
 *
 * Re-pointed machinery, not a second one: `buildOrgFleetData` already turns a team into a Glance
 * graph, and `studioNetworkForArchitect` is a plain team transform (the shape the request-session
 * augmentation shares). Everything downstream — node opening
 * (`studioPaneIdForNode`), live status (`applyStudioLiveStatus`), the morph — works unchanged,
 * because the node ids are the same Studio Network position ids in both graphs.
 *
 * Returns `null` when the team is absent, so the caller falls back to the empty graph rather than
 * crashing. Pure.
 */
export function buildArchitectFleetData(teams: readonly Team[], personas: Persona[]): GlanceData | null {
  const team = teams.find((t) => t.id === STUDIO_NETWORK_ID);
  if (!team) return null;
  // NOT augmented with the request sessions: they are not reachable from an architect verb, so they do
  // not belong in the graph of what the architect commands.
  return buildOrgFleetData(studioNetworkForArchitect(team), personas);
}

/**
 * The stable, app-owned session pane id for each base-studio-code studio graph node (#3319) — the studio
 * analogue of `fleetPaneId`. The node ids are the Studio Network team position ids
 * (`data/teams/orgs/planning-studio.json`), and each maps to its ONE app-owned session's fixed id
 * (`systemSessions.ts`). Because these ids are STABLE, opening a node re-uses the SAME session (its host
 * re-mounts it, `claude --continue`) rather than spawning a duplicate — the "reuse if it exists, create
 * if not" the studio sessions want. The `resource` nodes (libraries) and the dynamic `planner` session
 * have no fixed session, so they return null. Pure.
 */
const SINGLE_STUDIO_NODE_SESSION: Record<string, string> = {
  architect: TEAMS_STUDIO_SESSION_ID,
  "sound-designer": SOUND_STUDIO_SESSION_ID,
  integrator: INTEGRATION_STUDIO_SESSION_ID,
  // No `debugger` entry (#debug-nodes-hang-off-the-session-that-filed-them): the standing session is
  // gone, and a per-request session is DYNAMIC — resolved below from its node id, not from this map.
};

/** The technology a bare ROLE node opens — the one the app itself is built in.
 *
 *  The base-studio-code drill renders the PACKAGED team, which describes ROLES: its positions are the
 *  singular `designer` / `librarian` (see `studioNetworkForArchitect` for why the per-tech expansion
 *  lives in the transform rather than the JSON). Those role nodes must stay openable, so each names a
 *  default. This is a KIND-level fact about this repo, not a roster — it does not change when the
 *  algorithms graph gains or loses a language. */
const ROLE_NODE_DEFAULT_TECH: Record<string, string> = { designer: "react", librarian: "typescript" };

/** The pane a per-technology studio NODE (`designer-react`, `librarian-rust`) opens, or null.
 *
 *  A GRAMMAR since `the-studio-session-set-is-derived-not-declared`, where this was the per-technology
 *  half of a literal map built from two declared rosters. Those rosters are gone — the session set is
 *  a projection of the compiled studio KINDS over the technologies the stores actually hold — so the
 *  node id is parsed rather than looked up. The property that mattered is unchanged and is now
 *  structural rather than maintained: a technology that gains a session gains an openable, morphable,
 *  live-status-reporting node in the same instant, with no entry to remember. */
const PER_TECH_NODE = [
  { role: "designer", paneFor: designerSessionId },
  { role: "librarian", paneFor: librarianSessionId },
];

function perTechStudioNodePane(nodeId: string): string | null {
  for (const { role, paneFor } of PER_TECH_NODE) {
    if (!nodeId.startsWith(`${role}-`)) continue;
    const tech = nodeId.slice(role.length + 1);
    // Validated through the same predicate the pane grammar uses, so a node id and a pane id cannot
    // disagree about what counts as a technology.
    return studioPaneTech(paneFor(tech)) ? paneFor(tech) : null;
  }
  const dflt = ROLE_NODE_DEFAULT_TECH[nodeId];
  if (dflt) {
    const paneFor = PER_TECH_NODE.find((p) => p.role === nodeId)?.paneFor;
    return paneFor ? paneFor(dflt) : null;
  }
  return null;
}

/** The pane a fixed studio node opens, or null — the singles plus the per-technology grammar. */
function studioNodeSession(nodeId: string): string | null {
  return perTechStudioNodePane(nodeId) ?? SINGLE_STUDIO_NODE_SESSION[nodeId] ?? null;
}
/**
 * The INVERSE of {@link studioNodeSession} — a filing session's pane id → the graph node it is
 * (#debug-nodes-hang-off-the-session-that-filed-them).
 *
 * Built by inverting the table rather than by parsing the pane id, and that is the whole point. The
 * first version pattern-matched `<role>-studio:<tech>` and resolved EVERY studio origin to null,
 * because the real ids are `design-studio:designer-react` and `algorithms-studio:librarian-typescript`
 * — the studio is named for the SURFACE (design / algorithms / teams / sound / integration), not for
 * the role, and the role sits in the tail. Nothing caught it: tsc, eslint, 6823 vitest and clippy were
 * all green, because the tests asserted the same invented shape the code assumed. Only running the
 * binary did.
 *
 * Derived from the SAME grammar `studioNodeSession` reads, so the two cannot drift: a technology that
 * gains a session gains both directions at once, because neither is a list.
 */
function studioNodesForSession(paneId: string): string[] | null {
  // MANY node ids per session id, not one, and PER-TECHNOLOGY FIRST. `designer-react` and the packaged
  // ROLE node `designer` both open `design-studio:designer-react`, and the per-tech node is the one
  // that actually filed the request — so it is offered first and the role node is the fallback. The
  // old inversion of a literal map had to be careful not to let `Object.fromEntries` drop one of the
  // two; derived from the grammar, both are produced by construction.
  const per = studioPaneTech(paneId);
  if (per) {
    const nodes = [`${per.kind}-${per.tech}`];
    if (ROLE_NODE_DEFAULT_TECH[per.kind] === per.tech) nodes.push(per.kind);
    return nodes;
  }
  const single = Object.entries(SINGLE_STUDIO_NODE_SESSION).find(([, sid]) => sid === paneId);
  return single ? [single[0]] : null;
}

/**
 * Which node a request filed by `origin` should hang off, or null when this graph has none.
 *
 * `present` is the node set actually drawn, because the two studio drills render DIFFERENT ids for the
 * same session: the base-studio-code drill draws the packaged ROLE nodes (`designer`), the architect
 * drill draws per-technology ones (`designer-react`). The per-tech node is preferred where it exists —
 * it is the session that actually filed the request — and the role node is the fallback, so the same
 * request lands correctly in either graph instead of only one.
 *
 * Null for a pane that is not a studio session at all: a project director's `myproject:director` is a
 * legitimate origin whose request belongs in that project's drill (see {@link withProjectRequestNodes}),
 * and attaching it to a default node here would assert a relationship that does not exist.
 */
export const studioNodeForOrigin: OriginHostResolver = (origin, present) => {
  const o = (origin ?? "").trim();
  if (!o) return null;
  const candidates = studioNodesForSession(o);
  if (!candidates) return null;
  // Declaration order picks the winner, and the per-technology entries are declared first, so the
  // per-tech node wins where it is drawn (the architect drill).
  const drawn = candidates.find((nodeId) => present.has(nodeId));
  if (drawn) return drawn;
  // Otherwise fall back to the ROLE node the per-tech one expands from (`librarian-rust` → `librarian`),
  // which is what the packaged team draws. This is NOT covered by the candidate list: the role node maps
  // to ONE technology's session (`librarian` → the typescript librarian), so a rust librarian's request
  // has no candidate on the base-studio-code drill and would vanish from it entirely without this.
  for (const nodeId of candidates) {
    const role = nodeId.replace(/-[^-]+$/, "");
    if (role !== nodeId && present.has(role)) return role;
  }
  return null;
};

export function studioPaneIdForNode(nodeId: string): string | null {
  // A NETWORK'S ARCHITECT. The L0 architect node is now one per NETWORK rather than one per persona,
  // and its node id carries the network id (`architect:network-kitchen`), so its session resolves to
  // that network's pane (`network-kitchen:architect`) — the id `bsc session` also names and Rust
  // derives the workspace directory from.
  //
  // Like the request-session branch below it, this cannot live in the fixed map: a network is created
  // by the user at runtime. Without it the architect node resolves to no pane, which means it cannot
  // be opened, reports no live status, and is a session the user can neither watch nor stop.
  // A SURFACE SESSION (`a-noun-and-its-verbs-launch-their-personas`) — the operator on a noun, the
  // maintainer on a verb. Dynamic like the two branches below it: a noun exists because a crate serves
  // it, not because anyone enumerated it, so it cannot live in the fixed map. Without this the node
  // resolves to no pane, which means it cannot be opened, reports no live status, and is a session the
  // user can neither watch nor stop — the exact failure the integrator branch was added to fix.
  const surfacePane = surfacePaneIdForNode(nodeId);
  if (surfacePane) return surfacePane;
  const architectOf = architectIdOfNode(nodeId);
  if (architectOf && architectOf.startsWith("network-")) return `${architectOf}:architect`;
  // #3535: an overflow-pool session is DYNAMIC — one node per live pool slot — so it cannot live in the
  // fixed map above. Without this branch such a node resolves to no pane, which means it cannot be
  // opened, cannot report live status, and is a session the user can neither watch nor stop.
  const requestId = requestIdFromNodeId(nodeId);
  if (requestId !== null) return requestPaneId(requestId);
  return studioNodeSession(nodeId);
}

/** Where a studio node's session is HOSTED, so the graph can open/reveal it (#glance-resume). Since #3357
 *  the app-owned studio sessions live on the shared TerminalHost — the request sessions via
 *  `RequestSessionsMount`, the designer/librarian/architect via `StudioSessionHosts` — so every one of them is
 *  openable INLINE via the Glance `morph`: the host re-parents the single live terminal into the morph and
 *  hands it back to the studio's page dock on close, never spawning a second session. (Before #3357 the
 *  three studios ran their own single-mount xterm, which could not be re-parented, so they had to open on
 *  their workspace page instead — the `page` variant, kept for a future non-morphable node.) Null for a
 *  node with no openable session (the libraries, the dynamic planner). Pure. */
export type StudioNodeHome =
  | { kind: "morph" }
  | { kind: "page"; pageMode: "designs" | "algorithms" | "teams" };
export function studioNodeHome(nodeId: string): StudioNodeHome | null {
  // #3535: an overflow-pool session opens exactly like the studios it is one of.
  if (requestIdFromNodeId(nodeId) !== null) return { kind: "morph" };
  // DERIVED from `studioPaneIdForNode`, not a second hand-maintained list
  // (#architect-node-expands-into-system-sessions). This used to be a `switch` enumerating the studio
  // node ids, and it had silently fallen one behind: the INTEGRATOR (#4023) was added to
  // the studio node map — so it had a pane and reported live status — but never to this switch, so
  // its node returned null and could not be opened at all. A node that draws and does nothing is the
  // worst failure mode here, and it was invisible because nothing asserted the two lists agreed.
  //
  // The rule is exactly "a node that resolves to an app-owned pane opens as a morph", which is true by
  // construction since #3357 put every studio session on the shared TerminalHost. Deriving it means a
  // studio added to the registry is openable the same day.
  return studioPaneIdForNode(nodeId) ? { kind: "morph" } : null;
}

/**
 * Whether a base-studio-code studio node's session is currently ACTIVE (#glance-resume) — so the node
 * reflects a running session rather than a planned position. The DEBUGGER is live while the Settings
 * `debugSession` flag is on (its node only exists then anyway); the designer/librarian/architect are live
 * while their stable-id session is mounted + running (a live `paneClaudeActive` or a `run`/`on`
 * paneStatus). Pure so the liveness rule is unit-testable; the workspace passes the store signals.
 */
export function studioSessionLive(
  nodeId: string,
  signals: {
    paneClaudeActive: Record<string, boolean>;
    paneStatus: Record<string, string | undefined>;
    runState?: Record<string, string | undefined>;
  },
): boolean {
  const sid = studioPaneIdForNode(nodeId);
  if (!sid) return false;
  // THE BACKEND OWNS THIS FACT, and PRESENCE in its snapshot is the answer — not the status word.
  // A pane the reaper is tracking has a live PTY whatever its agent is doing, which is precisely the
  // distinction the two signals below cannot draw. They are written only by a mounted `TerminalView`
  // catching the OSC-100 marker as it goes past, and that marker is a one-shot EDGE emitted when the
  // harness binary is invoked. A session started headlessly and left running — every surface operator
  // and every local-model session — emits it with nothing listening, so both signals stay empty for
  // ever and the node rendered `off` while `bsc session activity` reported `status: run`.
  if (signals.runState && sid in signals.runState) return true;
  // A request session's node reports like every other one, off its own pane. It used to be special-cased
  // on the `debugSession` FLAG, which is gone with the standing node — and which was never the right
  // signal anyway: it said whether the toggle was on, not whether anything was running.
  return !!signals.paneClaudeActive[sid] || signals.paneStatus[sid] === "run" || signals.paneStatus[sid] === "on";
}

/** The store signals {@link applyStudioLiveStatus} reads — the same set {@link studioSessionLive} takes. */
export interface StudioLiveSignals {
  paneClaudeActive: Record<string, boolean>;
  paneStatus: Record<string, string | undefined>;
  /** The BACKEND's own run state per pane id (`pty_activity`): `run` · `idle` · `unknown`, and ABSENT
   *  for a pane it is not tracking. Optional so a caller with no backend read still type-checks and
   *  behaves exactly as before — this is ADDED to the two signals below, never swapped in for them. */
  runState?: Record<string, string | undefined>;
}

/**
 * Overlay the LIVE session state onto the base-studio-code project's studio nodes (#3421) — the studio
 * twin of `applyFleetLiveStatus`, and it exists because the two key their nodes DIFFERENTLY.
 *
 * A fleet node's pane id is `fleetPaneId(projectKey, nodeId)` (`<project>:<stream>`); a studio node's is
 * its STABLE app-owned session id from {@link studioPaneIdForNode} (`DESIGN_STUDIO_SESSION_ID`, …). Running
 * the fleet overlay over studio nodes therefore looked up `base-studio-code:designer`, which never exists,
 * so no studio node was ever found live. That mis-keying was invisible while an unmatched node fell through
 * to the raw `idle/idle` default (a plausible resting state) — #3415 made an unlaunched node read `off`,
 * which pinned every studio node `off` no matter what its session was doing.
 *
 * Health follows the #3415/#4042 model — existence AND work, not mere launch, on TWO independent axes:
 *
 *   - no session mounted                          → off · idle
 *   - mounted but quiet                           → healthy · idle
 *   - mounted + working (`paneStatus === "run"`)  → healthy · building
 *
 * The middle row is the one this got wrong for its whole life: BOTH the unmounted and the mounted-quiet
 * branch returned `off`, so {@link studioSessionLive} was dead weight and a studio the user was actively
 * talking to rendered dark unless `paneStatus` happened to read `run` at that exact instant. Its own doc
 * comment said otherwise, and so did the test's NAME — only the test's assertion agreed with the code,
 * which is what a test written from the implementation rather than the contract buys you. `healthy · idle`
 * is what the fleet twin (`applyFleetLiveStatus`) settled on in #4042 for the identical question, and
 * there is no reason for the two overlays to disagree about what a live-but-quiet session looks like.
 *
 * A node with NO fixed session (the `resource` libraries, the dynamic planner) is left untouched: it has no
 * runtime state of its own, so forcing it `off` would misreport a library as a dead session. Pure — apply to
 * `rawNodes` BEFORE `buildGraph` so the rollup recomputes over the live values.
 */
export function applyStudioLiveStatus(nodes: GRawNode[], signals: StudioLiveSignals): GRawNode[] {
  return nodes.map((n) => {
    if (n.preview) return n; // not a session node — its own state stands
    const sid = studioPaneIdForNode(n.id);
    if (!sid) return n; // a library/resource or the dynamic planner — no session to report on
    if (!studioSessionLive(n.id, signals)) {
      return { ...n, health: "off" as GHealth, activity: "idle" as GActivity };
    }
    // WORKING, from either publisher. The backend's `run` means the harness process is alive, which is
    // the same claim `paneStatus === "run"` makes from the other end — so a session reports `building`
    // whether or not anyone has its terminal open. `idle`/`unknown` fall through to the row below,
    // which is the state that had no reachable input before: a live PTY whose agent has exited.
    return signals.runState?.[sid] === "run" || signals.paneStatus[sid] === "run"
      ? { ...n, health: "healthy" as GHealth, activity: "building" as GActivity }
      // Mounted and quiet. `healthy` is the EXISTENCE axis (a session is there and nothing is wrong);
      // `idle` is the ACTIVITY axis (it is not working right now). Saying `off` here collapsed the two
      // axes back into one and threw away the only signal that distinguishes a running studio from one
      // that was never launched.
      : { ...n, health: "healthy" as GHealth, activity: "idle" as GActivity };
  });
}

/**
 * The crate drill, with its sessions' LIVE state on it.
 *
 * `crateDrillGraph` mints every node `off · idle` by construction — it is a pure projection of the
 * catalog and has no idea what is running. Nothing overlaid it, and the crate drill takes precedence
 * over the fleet drill in the page's `data`, so the noun and verb nodes rendered dead no matter what
 * their sessions were doing. MEASURED 2026-09-03: `pty-activity.json` reported
 * `surface-studio:noun-studio` as `status: run`, `onScreen: true`, while its node read idle.
 *
 * It is a NAMED composition rather than two calls inline in the page because that is what made the
 * gap invisible: the fleet drill's overlay and the crate drill's absence of one looked the same from
 * every test, since a pure projection passes identically whether or not anything overlays it. The
 * same reasoning `glanceFoldsAreCalled` was written for.
 *
 * `applyStudioLiveStatus` leaves a node with no app-owned pane untouched, so the crate node and any
 * dependency nodes keep exactly what the projection gave them.
 */
export function liveCrateDrill(doc: CrateDrillDoc, signals: StudioLiveSignals): GlanceData {
  const g = crateDrillGraph(doc);
  return { ...g, rawNodes: applyStudioLiveStatus(g.rawNodes, signals) };
}

/** How many spawners one column holds before the tier wraps. */
const TIER_WRAP = 6;
/** The clear gap between the two halves, so the split reads as a deliberate division. */
const TIER_GUTTER = ROWGAP * 0.75;
/** Breathing room between two adjacent cards, once their own footprint is accounted for. */
const CARD_GAP = 56;
/** How far LEFT of its spawner a debug session sits.
 *
 *  MEASURED FROM THE CARD, and that is the whole point. These were fractions of the layout gaps
 *  (`COLGAP * 0.62` = 156 and `ROWGAP * 0.62` = 63) while a node card is {@link NW}×{@link NH} =
 *  186×66 — so BOTH offsets were smaller than the card they were meant to step over, and every debug
 *  session overlapped the spawner it hung from while two siblings overlapped each other. An offset
 *  that does not exceed the card cannot separate two cards, however it is tuned. */
const DEBUG_DX = NW + CARD_GAP;
/** Vertical step between two debug sessions of the SAME spawner — see {@link DEBUG_DX} for why this is
 *  measured from {@link NH} rather than taken as a fraction of ROWGAP. Still tighter than a full row,
 *  so a spawner with three of them reads as one cluster. */
const DEBUG_DY = NH + CARD_GAP / 2;
/** Horizontal step between wrapped spawner COLUMNS.
 *
 *  Wider than a column on purpose: each spawner column reserves the width its own debug children
 *  occupy to its left ({@link DEBUG_DX}), so a wrapped column can never land on the previous column's
 *  children. The first attempt stepped half a column and produced exactly that overlap. */
const TIER_DX = COLGAP + DEBUG_DX;

/** Is this the node for another project's director? (The bare `director` root is NOT — it is the tier
 *  these hang from, and it keeps the position the DAG gave it.) */
const isPeerDirectorNode = (id: string): boolean => id.startsWith(PROJECT_DIRECTOR_PREFIX);
/** Is this a debug/request session node? */
const isRequestNode = (id: string): boolean => requestIdFromNodeId(id) !== null;

/**
 * Split the spawner tier into a TOP half (project directors) and a BOTTOM half (system sessions), and
 * park each debug session beside the spawner that filed it
 * (#the-studio-code-director-is-the-architect).
 *
 * THE DAG STAYS. Layering is untouched — this reorders WITHIN a layer. The barycenter pass interleaves
 * whatever shares a layer, so directors and studio sessions came out shuffled together with no way to
 * see which was which; they are different kinds of thing and the graph should say so.
 *
 * TWO THINGS THE FIRST VERSION GOT WRONG, both visible the moment it drew:
 *
 *  • It wrapped a long half LEFT by half a column — straight into the column the debug sessions were
 *    laid out in, so nodes overlapped. Columns now step by {@link TIER_DX}, which reserves the width a
 *    spawner's own children occupy, so a wrapped column cannot land on the previous one's cluster.
 *  • It moved the spawners and left their debug sessions where the DAG had put them, which broke the
 *    pairing it was supposed to show — a session ended up nowhere near whoever spawned it. Children now
 *    move WITH their parent, which is why this needs the edges.
 *
 * A debug session sits {@link DEBUG_DX} to its spawner's left, centred on it and stacked at
 * {@link DEBUG_DY} when a spawner has several — near enough to read as belonging to it.
 *
 * Pure: returns new nodes, mutates nothing. Untouched when the graph holds none of these.
 */
export function splitDirectorSessionTiers(nodes: readonly GNode[], edges: readonly GEdge[] = []): GNode[] {
  const byId = new Map(nodes.map((n) => [n.id, n]));
  // A request node is NOT a spawner, and the `!isRequestNode` guard is load-bearing:
  // `studioPaneIdForNode` deliberately resolves a pane for a debug node too (that is how one is
  // openable from its id alone), so without it every debug session was classed as a system session and
  // tiered into the bottom half — which is exactly why they appeared nowhere near whoever spawned them.
  const isSpawner = (n: GNode) =>
    !isRequestNode(n.id) && (isPeerDirectorNode(n.id) || studioPaneIdForNode(n.id) !== null);
  const spawners = nodes.filter(isSpawner);
  if (!spawners.length) return nodes as GNode[];

  // Each debug session's spawner, from the edge that points AT it. `from` is the host — every drawer
  // here writes the edge that way round (the spawner is blocked on the fix).
  const parentOf = new Map<string, string>();
  for (const e of edges) {
    if (isRequestNode(e.to) && byId.has(e.from)) parentOf.set(e.to, e.from);
  }
  const childrenOf = new Map<string, GNode[]>();
  for (const n of nodes) {
    const parent = isRequestNode(n.id) ? parentOf.get(n.id) : undefined;
    if (!parent) continue;
    (childrenOf.get(parent) ?? childrenOf.set(parent, []).get(parent)!).push(n);
  }

  const moved = new Map<string, { x: number; y: number }>();
  /** Park a spawner's debug sessions beside it, centred on its row. */
  const placeChildren = (parentId: string, x: number, y: number) => {
    const kids = childrenOf.get(parentId) ?? [];
    kids.forEach((k, i) => {
      moved.set(k.id, { x: x - DEBUG_DX, y: y + (i - (kids.length - 1) / 2) * DEBUG_DY });
    });
  };

  // ONE column for the whole tier — NOT one per DAG layer, and that distinction is the bug this
  // paragraph exists for. A spawner that has a debug session DEPENDS on it (`spawner → request`), so
  // the layout puts it one layer deeper than its childless peers. Grouping by `n.x` therefore handed
  // the single director with an open request a column of its own, where it was centred and tiered
  // alone — so the one director that had a debug session was the one that stopped lining up with the
  // others. Membership of the director tier is a fact about WHAT A NODE IS, not about what it happens
  // to depend on today, and laying it out per-column let a dependency silently redefine it.
  //
  // The leftmost column is the one taken, because a spawner's own children are placed further left
  // still ({@link DEBUG_DX}) and the deepest spawner is by definition the one that has them.
  const columnX = Math.min(...spawners.map((n) => n.x));
  const centre = spawners.reduce((sum, n) => sum + n.y, 0) / spawners.length;
  const place = (group: GNode[], dir: -1 | 1) =>
    group.forEach((n, i) => {
      const x = columnX - Math.floor(i / TIER_WRAP) * TIER_DX;
      const y = centre + dir * (TIER_GUTTER + (i % TIER_WRAP) * ROWGAP);
      moved.set(n.id, { x, y });
      placeChildren(n.id, x, y);
    });
  place(spawners.filter((n) => isPeerDirectorNode(n.id)), -1);
  place(spawners.filter((n) => !isPeerDirectorNode(n.id)), 1);

  // THE ARCHITECT'S OWN debug sessions stack BELOW it, not to its left like everyone else's.
  //
  // These are the requests no project director filed — a human at a shell — which
  // `withUnparentedRequestNodes` now edges to the architect. The architect sits to the RIGHT of the
  // whole spawner tier (it is what the tier hangs from), so "to its left" is precisely where the tier's
  // own columns are: parking them there puts a human-filed session inside the director group, reading
  // as though some director owned it. Below the architect there is nothing else, so the column is free
  // and the grouping is unambiguous.
  const root = byId.get(DIRECTOR_NODE);
  if (root) {
    (childrenOf.get(DIRECTOR_NODE) ?? []).forEach((k, i) => {
      moved.set(k.id, { x: root.x, y: root.y + ROWGAP + i * DEBUG_DY });
    });
  }

  return nodes.map((n) => {
    const at = moved.get(n.id);
    return at ? { ...n, x: at.x, y: at.y } : n;
  });
}

