// ── withStudioSessions (#the-app-drills-into-a-project-that-was-deleted) ─────────────────────────────
describe("withStudioSessions — the app's sessions fold into its project's drill", () => {
  const fleetNode = (id: string) => ({ id, slug: id, role: "service" as const, roleLabel: "worker", health: "off" as const, activity: "idle" as const });
  const fleet = (ids: string[]): GlanceData => ({
    rawNodes: ids.map(fleetNode),
    rawEdges: [],
    sample: false,
  });

  it("adds the app-owned SESSIONS beside the project's own workers", () => {
    const out = withStudioSessions(fleet(["cli-platform", "console"]), BUILTIN_ORGS, BUILTIN_PERSONAS, []);
    const ids = out.rawNodes.map((n) => n.id);
    expect(ids).toEqual(expect.arrayContaining([
      "cli-platform", "console", "designer-react", "librarian-typescript", "architect",
    ]));
    // Every folded node opens something. A node that draws and does nothing is the failure mode this
    // codebase keeps rediscovering, so the fold is defined as "resolves to an app-owned pane".
    const folded = ids.filter((id) => !["cli-platform", "console"].includes(id));
    for (const id of folded) expect(studioPaneIdForNode(id)).not.toBeNull();
  });

  it("folds NO library/resource node — they collide with real stream ids and have their own L0 band", () => {
    const out = withStudioSessions(fleet([]), BUILTIN_ORGS, BUILTIN_PERSONAS, []);
    const ids = out.rawNodes.map((n) => n.id);
    // The studio team names its libraries for domains the app's own fleet also has streams for.
    expect(ids).not.toContain("algorithms");
    expect(ids).not.toContain("sounds");
    expect(ids).not.toContain("integrations");
    // …and the `planner` position has no fixed session, so it would draw a node that does nothing.
    expect(ids).not.toContain("planner");
  });

  it("a fleet stream that SHARES a studio node's id keeps its own node — the fleet owns its drill", () => {
    // Same name, different thing. Merging over it would hand a worker a studio's identity; skipping is
    // the honest degradation, and the edge rule below stops the skip from leaving a dangling claim.
    // The collision id follows the node set: since the drill expanded per technology, a fleet stream
    // called `designer` no longer shares an id with anything the studio folds, so the case has to be
    // stated against an id that DOES collide or it stops testing collision at all.
    const out = withStudioSessions(fleet(["designer-react"]), BUILTIN_ORGS, BUILTIN_PERSONAS, []);
    expect(out.rawNodes.filter((n) => n.id === "designer-react")).toHaveLength(1);
    expect(out.rawNodes.find((n) => n.id === "designer-react")!.roleLabel).toBe("worker");
  });

  it("keeps an edge only when BOTH ends were folded", () => {
    // With `designer` skipped as a collision, the designer↔librarian edge must NOT be drawn — it would
    // assert a studio relationship about a fleet worker that happens to share the name.
    const out = withStudioSessions(fleet(["designer-react"]), BUILTIN_ORGS, BUILTIN_PERSONAS, []);
    expect(out.rawEdges.some((e) => e.from === "designer-react" || e.to === "designer-react")).toBe(false);
  });

  it("carries the live request sessions in, edged to the session that filed them", () => {
    const out = withStudioSessions(fleet(["cli-platform"]), BUILTIN_ORGS, BUILTIN_PERSONAS, [
      { id: 96, origin: designerSessionId("react"), title: "ui remove does not stick" },
      { id: 93, origin: null, title: "navigate times out" },
    ]);
    const ids = out.rawNodes.map((n) => n.id);
    expect(ids).toContain("debugger-req-96");
    // The origin-less one too — nothing else can host it, so dropping it here hides a running session.
    expect(ids).toContain("debugger-req-93");
    // THE REPORTED BUG: this edge used to land on the shared `designer` role node whatever technology
    // filed the request. It now names the session that actually did.
    expect(out.rawEdges).toContainEqual(expect.objectContaining({ from: "designer-react", to: "debugger-req-96" }));
    expect(out.rawEdges.some((e) => e.from === "debugger-req-93" || e.to === "debugger-req-93")).toBe(false);
  });

  it("is idempotent — folding twice never doubles a node", () => {
    const once = withStudioSessions(fleet(["console"]), BUILTIN_ORGS, BUILTIN_PERSONAS, []);
    const twice = withStudioSessions(once, BUILTIN_ORGS, BUILTIN_PERSONAS, []);
    expect(twice.rawNodes).toHaveLength(once.rawNodes.length);
    expect(twice.rawEdges).toHaveLength(once.rawEdges.length);
  });

  it("returns the graph UNTOUCHED when the Studio Network team is absent", () => {
    const base = fleet(["console"]);
    expect(withStudioSessions(base, [], BUILTIN_PERSONAS, [])).toBe(base);
  });

  it("preserves the fleet graph's own fields", () => {
    const base = { ...fleet(["console"]), sample: true };
    expect(withStudioSessions(base, BUILTIN_ORGS, BUILTIN_PERSONAS, []).sample).toBe(true);
  });
});


// ── withUnparentedRequestNodes (#every-live-debug-session-is-visible-in-the-app-drill) ───────────────
//
// THE ORIGINS HERE ARE REAL, read off the live queue while two debug sessions were running, because the
// bug survived a green suite that asserted invented shapes. `design-studio:designer-react` is what a
// designer session actually stamps (the studio is named for the SURFACE, the role sits in the tail);
// `kevin` is what `bsc request new --from` writes; `network-monitor:director` is another project's
// director. Only the first of those three was ever drawn.
describe("withUnparentedRequestNodes — a live session is VISIBLE even when it cannot be related", () => {
  const drill = (ids: string[] = []): GlanceData => ({
    rawNodes: ids.map((id) => ({
      id, slug: id, role: "service" as const, roleLabel: "worker", health: "off" as const, activity: "idle" as const,
    })),
    rawEdges: [],
    sample: false,
  });

  it("draws a request whose origin resolves to NOTHING — the live session that had no node anywhere", () => {
    // `kevin` is a person at a shell, not a pane. `withStudioSessions` skipped it (an origin is a claim
    // another graph might host) and `withProjectRequestNodes` skipped it (not `<project>:director`), so
    // a running, busy PTY was invisible in every graph. That is the defect.
    const out = withUnparentedRequestNodes(drill(["api"]), [
      { id: 107, origin: "kevin", title: "No verb amends one field of an issue" },
    ]);
    expect(out.rawNodes.map((n) => n.id)).toContain("debugger-req-107");
    // …and it is OPENABLE, which is the whole point of drawing it: a node that cannot be opened is a
    // worse outcome than no node, and this codebase has shipped that failure before.
    expect(studioPaneIdForNode("debugger-req-107")).toBe("debug-studio:req-107");
  });

  it("draws ANOTHER project's director-filed request too — unrelatable here, still visible", () => {
    const out = withUnparentedRequestNodes(drill(), [
      { id: 42, origin: "network-monitor:director", title: "publish run cannot target a fork" },
    ]);
    expect(out.rawNodes.map((n) => n.id)).toContain("debugger-req-42");
  });

  it("edges a human-filed request to the ARCHITECT — the tier that owns the tooling queue", () => {
    // This test used to assert the OPPOSITE ("draws NO edge — there is nothing truthful to point at"),
    // and that was right until the app's own director became the architect. A request filed by a person
    // at a shell IS the architect's: it answers for everything no project director does. Two of these
    // (`kevin`, a dev session) were floating in the app drill with no relationship at all.
    const out = withUnparentedRequestNodes(drill(["director", "api"]), [{ id: 107, origin: "kevin", title: "t" }]);
    expect(out.rawEdges).toContainEqual(
      expect.objectContaining({ from: "director", to: "debugger-req-107" }),
    );
  });

  it("still draws NO edge when the architect is not in the graph", () => {
    // A non-app project's drill has no `director` root. VISIBILITY must not depend on finding a parent
    // — that guarantee is the whole reason this sweep exists — so the node is drawn bare rather than
    // hung off something that is not there.
    const out = withUnparentedRequestNodes(drill(["api"]), [{ id: 107, origin: "kevin", title: "t" }]);
    expect(out.rawNodes.map((n) => n.id)).toContain("debugger-req-107");
    expect(out.rawEdges).toHaveLength(0);
  });

  it("leaves a request another drawer already drew ALONE — it must not steal an edge", () => {
    // The ordering guarantee, asserted rather than trusted. This is what makes the sweep safe to run
    // after `withProjectRequestNodes`: the director-edged node is already `present`, so the sweep is a
    // no-op on it and the edge survives.
    const withDirector = withProjectRequestNodes(drill(["director"]), "myproject", [
      { id: 5, origin: "myproject:director", title: "board is stale" },
    ]);
    const swept = withUnparentedRequestNodes(withDirector, [
      { id: 5, origin: "myproject:director", title: "board is stale" },
    ]);
    expect(swept.rawNodes.filter((n) => n.id === "debugger-req-5")).toHaveLength(1);
    expect(swept.rawEdges).toContainEqual(expect.objectContaining({ from: "director", to: "debugger-req-5" }));
  });

  it("a node it draws is INDISTINGUISHABLE from a related one, apart from the edge", () => {
    // Same role/label/health/activity — "unrelated" must not render as "a different kind of thing".
    const related = withProjectRequestNodes(drill(["director"]), "myproject", [
      { id: 5, origin: "myproject:director", title: "board is stale" },
    ]).rawNodes.find((n) => n.id === "debugger-req-5")!;
    const orphan = withUnparentedRequestNodes(drill(), [
      { id: 5, origin: "kevin", title: "board is stale" },
    ]).rawNodes.find((n) => n.id === "debugger-req-5")!;
    expect(orphan).toEqual(related);
  });

  it("is idempotent, and de-duplicates rows that repeat an id within one call", () => {
    // `present` is sampled once, before anything is pushed, so two rows carrying one id would both pass
    // it and draw the session twice.
    const once = withUnparentedRequestNodes(drill(["api"]), [{ id: 107, origin: "kevin", title: "t" }]);
    const twice = withUnparentedRequestNodes(once, [{ id: 107, origin: "kevin", title: "t" }]);
    expect(twice.rawNodes).toHaveLength(once.rawNodes.length);
    const dupes = withUnparentedRequestNodes(drill(), [
      { id: 9, origin: "kevin", title: "a" },
      { id: 9, origin: null, title: "a" },
    ]);
    expect(dupes.rawNodes.filter((n) => n.id === "debugger-req-9")).toHaveLength(1);
  });

  it("is a no-op with no requests, and preserves the graph's own fields", () => {
    const base = { ...drill(["api"]), sample: true };
    expect(withUnparentedRequestNodes(base, [])).toBe(base);
    expect(withUnparentedRequestNodes(base, [{ id: 1, origin: null, title: "t" }]).sample).toBe(true);
  });

  it("END TO END: every live session gets a node, whatever its origin", () => {
    // The three live shapes plus an origin-less one, through the REAL ladder in the real order. This is
    // the acceptance criterion: four running sessions, four nodes.
    const requests = [
      { id: 106, origin: designerSessionId("react"), title: "algorithms.json not vendored" },
      { id: 107, origin: "kevin", title: "No verb amends one field of an issue" },
      { id: 42, origin: "network-monitor:director", title: "publish run cannot target a fork" },
      { id: 93, origin: null, title: "navigate times out" },
    ];
    const studio = withStudioSessions(drill(["cli-platform"]), BUILTIN_ORGS, BUILTIN_PERSONAS, requests);
    const out = withUnparentedRequestNodes(
      withProjectRequestNodes(studio, APP_PROJECT_KEY, requests),
      requests,
    );
    const ids = out.rawNodes.map((n) => n.id);
    for (const r of requests) expect(ids).toContain(`debugger-req-${r.id}`);
    // The one that CAN be related still is — visibility was added, nothing was traded for it.
    expect(out.rawEdges).toContainEqual(expect.objectContaining({ from: "designer-react", to: "debugger-req-106" }));
  });
});

describe("livePanesForDrilledProject (the app project counts its debug sessions)", () => {
  // The reported bug: debug sessions run against base-studio-code, the studio-code drill DRAWS them as
  // nodes, and the "End N sessions" counter read 0 — because a debug pane is `debug-studio:req-<id>`
  // and the counter matched only the `studio-code:` prefix.
  const live = new Set([
    "studio-code:director",
    "debug-studio:req-118",
    "debug-studio:req-123",
    "network-monitor:director",
  ]);

  it("counts the app project's request sessions alongside its own prefixed panes", () => {
    expect(livePanesForDrilledProject(APP_PROJECT_KEY, live).sort()).toEqual([
      "debug-studio:req-118",
      "debug-studio:req-123",
      "studio-code:director",
    ]);
  });

  it("does NOT lend a request to a project whose director did not file it", () => {
    // The requests above carry no origin, so they are nobody's but the app's. A project that did not
    // file one must not acquire it — a drill showing debug work that has nothing to do with it is the
    // failure the app-project gate was protecting against, and it still holds.
    expect(livePanesForDrilledProject("network-monitor", live)).toEqual(["network-monitor:director"]);
  });

  // ── a NON-APP project counts its own (#a-projects-debug-sessions-are-drawn-but-not-counted) ──────
  //
  // Reported live: Network Monitor ran a director and two debug sessions (requests 127/128, both
  // `origin: network-monitor:director`), the drill DREW both as nodes off the director, and the header
  // bar counted zero. `withProjectRequestNodes` hangs a node off any project's director by that origin
  // rule; this function gated the same sessions on `isAppProject`. The graph showed them and the
  // toolbar denied them — the exact shape of the app-project bug, one project over.
  describe("a project counts the debug sessions its own director filed", () => {
    const nmLive = new Set(["network-monitor:director", "debug-studio:req-127", "debug-studio:req-128"]);
    const nmRequests = [
      { id: 127, origin: "network-monitor:director", title: "wrong plan db" },
      { id: 128, origin: "network-monitor:director", title: "wrong plan db again" },
    ];

    it("counts them alongside its own prefixed panes", () => {
      expect(livePanesForDrilledProject("network-monitor", nmLive, nmRequests).sort()).toEqual([
        "debug-studio:req-127",
        "debug-studio:req-128",
        "network-monitor:director",
      ]);
    });

    it("counts exactly what the drill DREW — no more", () => {
      // The invariant that makes this durable: the counter applies the drawers' own membership rule,
      // so a session the graph renders and a session the toolbar counts are the same set by
      // construction rather than by two conditions that happen to agree.
      const drawn = withProjectRequestNodes(
        { rawNodes: [{ id: "director", slug: "director", role: "infra", health: "healthy", activity: "idle" }], rawEdges: [] } as unknown as GlanceData,
        "network-monitor",
        nmRequests,
      );
      const drawnIds = drawn.rawNodes.filter((n) => n.id.startsWith("debugger-req-")).length;
      const counted = livePanesForDrilledProject("network-monitor", nmLive, nmRequests)
        .filter((p) => p.startsWith("debug-studio:req-")).length;
      expect(counted).toBe(drawnIds);
    });

    it("ignores a request ANOTHER project's director filed", () => {
      const foreign = [{ id: 127, origin: "other-project:director", title: "not ours" }];
      expect(livePanesForDrilledProject("network-monitor", nmLive, foreign)).toEqual([
        "network-monitor:director",
      ]);
    });

    it("ignores a request filed by a STUDIO session, which hangs off the studio graph instead", () => {
      const studioFiled = [{ id: 127, origin: "design-studio:designer-react", title: "kit thing" }];
      expect(livePanesForDrilledProject("network-monitor", nmLive, studioFiled)).toEqual([
        "network-monitor:director",
      ]);
    });

    it("still gives the APP project every live request, including ones no drawer could parent", () => {
      // The app draws the unparented sweep too, so narrowing it to the origin rule would be a
      // regression of the fix this one generalizes.
      const orphan = [{ id: 127, origin: "somebody:else", title: "filed at a shell" }];
      expect(livePanesForDrilledProject(APP_PROJECT_KEY, new Set(["debug-studio:req-127"]), orphan))
        .toEqual(["debug-studio:req-127"]);
    });
  });

  it("leaves the standing studios out — they are singletons, not a project's fleet to bulk-end", () => {
    const withStudios = new Set([...live, "design-studio:designer-react", "teams-studio:architect"]);
    const out = livePanesForDrilledProject(APP_PROJECT_KEY, withStudios);
    expect(out).not.toContain("design-studio:designer-react");
    expect(out).not.toContain("teams-studio:architect");
  });

  it("never double-counts a pane that both rules could claim", () => {
    const out = livePanesForDrilledProject(APP_PROJECT_KEY, live);
    expect(new Set(out).size).toBe(out.length);
  });

  it("is empty for a blank key, and unchanged for a project with no request sessions", () => {
    expect(livePanesForDrilledProject("", live)).toEqual([]);
    expect(livePanesForDrilledProject("ghost", live)).toEqual([]);
  });
});

// ── the expanded nodes are LABELLED (#the-project-drill-draws-per-technology-studio-nodes) ─────────
describe("an expanded studio node says which technology it is", () => {
  it("labels each per-tech node, so two designers are not both drawn as `Designer`", () => {
    // The expansion used to spread the role position wholesale — same `personaId`, no `label` — and a
    // node's slug is `label ?? persona.name ?? nodeId`. Both designers therefore rendered as
    // "Designer" in the one drill that drew them, which is the "unlabelled designer node" in the
    // report. The label is the node id because that is the name the user already has for these: it is
    // what `bsc session list` prints and what the pane id carries.
    const data = buildStudioFleetData(BUILTIN_ORGS, BUILTIN_PERSONAS, [])!;
    const slugOf = (id: string) => data.rawNodes.find((n) => n.id === id)?.slug;
    expect(slugOf("designer-react")).toBe("designer-react");
    expect(slugOf("designer-react-native")).toBe("designer-react-native");
    expect(slugOf("librarian-rust")).toBe("librarian-rust");
    const designers = data.rawNodes.filter((n) => n.id.startsWith("designer-")).map((n) => n.slug);
    expect(new Set(designers).size, `both designers must be distinguishable: ${designers.join(", ")}`)
      .toBe(designers.length);
  });

  it("keeps the network's own relationships across the expansion instead of dangling them", () => {
    // `librarian serves designer` is the one studio-to-studio edge this drill draws. Expanding both
    // ends without remapping would leave it pointing at ids nothing renders — the edge would simply
    // vanish, and the drill would say the studios do not talk to each other.
    const data = buildStudioFleetData(BUILTIN_ORGS, BUILTIN_PERSONAS, [])!;
    const ids = new Set(data.rawNodes.map((n) => n.id));
    for (const e of data.rawEdges) {
      expect(ids.has(e.from), `edge from ${e.from} dangles`).toBe(true);
      expect(ids.has(e.to), `edge to ${e.to} dangles`).toBe(true);
    }
    // Fanned across both ends: every librarian serves every designer (the graph is a lens, not a
    // partition — a React component resolves a TypeScript implementation).
    expect(data.rawEdges).toContainEqual(expect.objectContaining({ from: "designer-react", to: "librarian-rust" }));
  });
});

