// The two kinds share a DAG layer, and the barycenter pass interleaved them — so a column of directors
// and studio sessions came out shuffled with no way to see which was which.
describe("splitDirectorSessionTiers", () => {
  const at = (id: string, x: number, y: number) => ({ id, x, y, slug: id, layer: 1 }) as never;
  const edge = (from: string, to: string) => ({ id: `${from}>${to}`, from, to, kind: "api" }) as never;
  /** No two nodes may sit within a node's own footprint of each other — the overlap the first version drew. */
  // MEASURED AGAINST THE REAL CARD (NW×NH = 186×66). It used to say 80×40, which is smaller than a card
  // and so reported "no overlap" for placements that visibly overlapped — the offsets it was guarding
  // were themselves under the card size and it passed anyway.
  const overlaps = (ns: { x: number; y: number }[]) =>
    ns.some((a, i) => ns.some((b, j) => i !== j && Math.abs(a.x - b.x) < NW && Math.abs(a.y - b.y) < NH));

  it("puts directors above the divide and system sessions below", () => {
    const out = splitDirectorSessionTiers([
      at(projectDirectorNodeId("a"), 500, 100),
      at("designer-react", 500, 200),
      at(projectDirectorNodeId("b"), 500, 300),
    ], []);
    const y = (id: string) => out.find((n) => n.id === id)!.y;
    expect(y(projectDirectorNodeId("a"))).toBeLessThan(y("designer-react"));
    expect(y(projectDirectorNodeId("b"))).toBeLessThan(y("designer-react"));
  });

  it("keeps a director that HAS a debug session in line with the directors that do not", () => {
    // THE REGRESSION. `spawner → request` is a dependency edge, so the layout puts a director with an
    // open request one layer deeper (x=248 here) than its childless peers (x=500). Tiering per column
    // then gave that one director a column to itself, centred it alone, and it stopped lining up with
    // the others — the network-monitor director, the only one with a live request. Tier membership is
    // a fact about what a node IS, not about what it currently depends on.
    const withKid = projectDirectorNodeId("network-monitor");
    const out = splitDirectorSessionTiers(
      [
        at(projectDirectorNodeId("a"), 500, 100),
        at(projectDirectorNodeId("b"), 500, 300),
        at(withKid, 248, 700),
        at("debugger-req-142", 0, 900),
      ],
      [edge(withKid, "debugger-req-142")],
    );
    const dirs = [projectDirectorNodeId("a"), projectDirectorNodeId("b"), withKid]
      .map((id) => out.find((n) => n.id === id)!);
    expect(new Set(dirs.map((d) => d.x)).size).toBe(1);      // one column, not two
    expect(new Set(dirs.map((d) => d.y)).size).toBe(3);      // and stacked, not piled up
    // Its debug session came with it rather than being left behind at the DAG's y=900.
    expect(out.find((n) => n.id === "debugger-req-142")!.y)
      .toBeCloseTo(out.find((n) => n.id === withKid)!.y, 0);
  });

  it("moves a debug session WITH its spawner, and keeps it beside it", () => {
    const dir = projectDirectorNodeId("a");
    const req = "debugger-req-7";
    const out = splitDirectorSessionTiers(
      [at(dir, 500, 100), at("designer-react", 500, 200), at(req, 100, 900)],
      [edge(dir, req)],
    );
    const d = out.find((n) => n.id === dir)!;
    const r = out.find((n) => n.id === req)!;
    // It followed its spawner rather than staying at the DAG's y=900 — that break is what made the
    // pairing unreadable — and it sits just LEFT of it, close enough to read as one unit.
    expect(r.y).toBeCloseTo(d.y, 0);
    expect(r.x).toBeLessThan(d.x);
    expect(d.x - r.x).toBeLessThan(252); // inside one column gap
  });

  it("CLEARS its spawner's card rather than merely sitting left of it", () => {
    // The offsets were fractions of the layout gaps (COLGAP*0.62 = 156, ROWGAP*0.62 = 63) while a card
    // is 186×66 — so every debug session overlapped the spawner it hung from, and two siblings
    // overlapped each other. "Left of" is not "clear of" unless the step exceeds the card.
    const dir = projectDirectorNodeId("a");
    const kids = ["debugger-req-1", "debugger-req-2"];
    const out = splitDirectorSessionTiers(
      [at(dir, 500, 100), ...kids.map((k, i) => at(k, 100, 900 + i))],
      kids.map((k) => edge(dir, k)),
    );
    const d = out.find((n) => n.id === dir)!;
    for (const k of kids) expect(d.x - out.find((n) => n.id === k)!.x).toBeGreaterThanOrEqual(NW);
    const [a, b] = kids.map((k) => out.find((n) => n.id === k)!);
    expect(Math.abs(a.y - b.y)).toBeGreaterThanOrEqual(NH);
    expect(overlaps([d, a, b])).toBe(false);
  });

  it("stacks the ARCHITECT's own debug sessions BELOW it, not into the director tier", () => {
    // A human-filed request edges to the architect, and the architect sits RIGHT of the whole tier — so
    // parking its children "to its left" like everyone else's drops them among the directors, reading as
    // though a director owned them. Below it, the column is free.
    const kids = ["debugger-req-146", "debugger-req-149"];
    const out = splitDirectorSessionTiers(
      [at("director", 900, 400), at(projectDirectorNodeId("a"), 500, 100), ...kids.map((k) => at(k, 100, 900))],
      kids.map((k) => edge("director", k)),
    );
    const root = out.find((n) => n.id === "director")!;
    const placed = kids.map((k) => out.find((n) => n.id === k)!);
    for (const p of placed) {
      expect(p.x).toBe(root.x);          // directly under it, not off to one side
      expect(p.y).toBeGreaterThan(root.y);
    }
    expect(overlaps([root, ...placed])).toBe(false);
    // And they are nowhere near the director tier's column.
    expect(placed.every((p) => p.x > out.find((n) => n.id === projectDirectorNodeId("a"))!.x)).toBe(true);
  });

  it("stacks several debug sessions of one spawner without overlapping them", () => {
    const dir = projectDirectorNodeId("a");
    const kids = ["debugger-req-1", "debugger-req-2", "debugger-req-3"];
    const out = splitDirectorSessionTiers(
      [at(dir, 500, 100), ...kids.map((k, i) => at(k, 100, 900 + i))],
      kids.map((k) => edge(dir, k)),
    );
    expect(overlaps(out.filter((n) => kids.includes(n.id)))).toBe(false);
  });

  it("wraps a long tier WITHOUT landing on the previous column's debug cluster", () => {
    // 8 directors ⇒ two columns; each with a debug child, which is what the first version overlapped.
    const dirs = Array.from({ length: 8 }, (_, i) => projectDirectorNodeId(`p${i}`));
    const nodes = [
      ...dirs.map((d, i) => at(d, 500, 100 + i * 10)),
      ...dirs.map((d, i) => at(`debugger-req-${i}`, 100, 900 + i)),
    ];
    const out = splitDirectorSessionTiers(nodes, dirs.map((d, i) => edge(d, `debugger-req-${i}`)));
    expect(new Set(out.filter((n) => dirs.includes(n.id)).map((n) => n.x)).size).toBeGreaterThan(1);
    expect(overlaps(out)).toBe(false);
  });

  it("leaves a graph with neither kind completely untouched", () => {
    const plain = [at("worker-1", 100, 100), at("worker-2", 100, 200)];
    expect(splitDirectorSessionTiers(plain, [])).toEqual(plain);
  });
});

// ── the crate drill carries its sessions' state (`the-crate-drill-shows-its-sessions-live`) ────────
//
// `crateDrillGraph` mints every node `off · idle` — it is a pure projection of the catalog and knows
// nothing about what is running — and NOTHING overlaid it, while the crate drill takes precedence
// over the fleet drill in the page's `data`. So a noun or verb node rendered dead whatever its
// session was doing. MEASURED: `pty-activity.json` reported `surface-studio:noun-studio` as
// `status: run`, `onScreen: true`, while its node read idle.
describe("liveCrateDrill", () => {
  const doc = {
    crate: "bsc-studio", path: "crates/bsc-studio", surface: true,
    nouns: [{ noun: "studio", verbs: [{ verb: "list" }] }],
    dependsOn: [], dependents: [], dependentCount: 0,
  } as unknown as Parameters<typeof liveCrateDrill>[0];
  const sig = (runState: Record<string, string | undefined>) =>
    ({ paneClaudeActive: {}, paneStatus: {}, runState });
  const nodeOf = (g: ReturnType<typeof liveCrateDrill>, id: string) => g.rawNodes.find((n) => n.id === id);

  it("shows a RUNNING noun session as healthy · building, not idle", () => {
    const g = liveCrateDrill(doc, sig({ "surface-studio:noun-studio": "run" }));
    expect(nodeOf(g, "noun:studio")).toMatchObject({ health: "healthy", activity: "building" });
  });

  it("shows a live-but-quiet session as healthy · idle — a session exists, it just is not working", () => {
    const g = liveCrateDrill(doc, sig({ "surface-studio:noun-studio": "idle" }));
    expect(nodeOf(g, "noun:studio")).toMatchObject({ health: "healthy", activity: "idle" });
  });

  it("leaves a node whose session is not running as the projection minted it", () => {
    const g = liveCrateDrill(doc, sig({}));
    expect(nodeOf(g, "noun:studio")).toMatchObject({ health: "off", activity: "idle" });
  });

  // Keyed per node: one running session must not light up its neighbours, and the VERB node resolves
  // its own pane through the same grammar.
  it("keys each node by its own pane", () => {
    const g = liveCrateDrill(doc, sig({ "surface-studio:verb-studio-list": "run" }));
    expect(nodeOf(g, "verb:studio:list")).toMatchObject({ health: "healthy", activity: "building" });
    expect(nodeOf(g, "noun:studio")?.health).toBe("off");
  });

  it("carries the projection's edges through untouched", () => {
    const g = liveCrateDrill(doc, sig({}));
    expect(g.rawEdges.length).toBeGreaterThan(0);
  });
});
